/** Order matters: stored avatar values refer to a shape by its index here. */
export const SHAPE_KEYS = [
    "hex",
    "wedge",
    "squircle",
    "tablet",
    "pebble",
    "blob",
    "teardrop",
    "cloud",
    "heart",
    "starburst",
    "flower",
    "clover",
    "star",
    "ghost",
    "mushroom",
    "bell",
    "sparkle",
    "jelly",
    "cat",
    "diamond",
    "shield",
    "acorn",
    "egg",
];
/** How far the eyes may travel (gaze = +-1) per shape; narrow shapes get less so the eyes stay inside. */
const NARROW = {
    wedge: { x: 11, y: 8 },
    heart: { x: 15, y: 9 },
    mushroom: { x: 22, y: 10 },
    sparkle: { x: 12, y: 8 },
};
export function gazeTravel(shape) {
    return NARROW[shape] ?? { x: 22, y: 16 };
}
/** A shape by key or by index (wraps, so any integer is valid). Unknown keys fall back to `hex`. */
export function resolveShape(shape) {
    if (typeof shape === "number") {
        const n = Number.isFinite(shape) ? Math.trunc(shape) : 0;
        return SHAPE_KEYS[((n % SHAPE_KEYS.length) + SHAPE_KEYS.length) % SHAPE_KEYS.length] ?? "hex";
    }
    return SHAPE_KEYS.includes(shape ?? "") ? shape : "hex";
}
